export const IDEA_TO_PROTOTYPE_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu prototipe & kenapa membuatnya
{n:1,type:"mcq",micro:"Apa itu prototipe",q:"'Prototipe' (purwarupa) adalah...",options:["Versi kasar & cepat dari sebuah ide yang dibuat untuk dilihat, dicoba, & dipelajari","Versi akhir yang sudah sempurna & siap dipakai selamanya","Gambar indah yang hanya untuk dipajang"],answer:0,explain:"Prototipe sengaja dibuat kasar & cepat. Tujuannya belajar apa yang berhasil & apa yang perlu diperbaiki, bukan langsung sempurna.",hint:"Versi kasar untuk belajar, atau versi akhir sempurna?"},
{n:2,type:"mcq",micro:"Kenapa membuat prototipe",q:"Kenapa membuat versi kasar dulu, bukan langsung versi jadi?",options:["Karena versi jadi tidak pernah dibutuhkan","Supaya kesalahan ketahuan saat masih murah & cepat diperbaiki, sebelum banyak waktu & bahan terpakai","Supaya terlihat sibuk"],answer:1,explain:"Menemukan 'ternyata pegangannya terlalu kecil' di model kardus jauh lebih murah daripada menemukannya setelah 100 unit dibuat.",hint:"Menemukan kesalahan saat masih murah, atau sekadar sibuk?"},
{n:3,type:"mcq",micro:"Prototipe murah & cepat",q:"Prinsip 'murah & cepat' dalam membuat prototipe berarti...",options:["Pakai bahan termahal supaya kuat","Habiskan sebulan agar rapi","Pakai bahan seadanya (kertas, kardus, barang bekas) & jangan habiskan waktu memperindah"],answer:2,explain:"Prototipe yang terlalu bagus membuat kita sayang mengubahnya. Yang kasar mudah dicoret & dibuat ulang.",hint:"Seadanya & cepat, atau mahal & lama?"},
{n:4,type:"mcq",micro:"Jenis prototipe: sketsa",q:"Bentuk prototipe paling cepat untuk ide tampilan/tata letak:",options:["Sketsa tangan di kertas, kotak-kotak & garis kasar untuk menunjukkan susunannya","Gambar digital yang sangat detail","Tidak ada, harus langsung dibuat"],answer:0,explain:"Sketsa kertas bisa dibuat & diubah dalam hitungan menit, sempurna untuk mencoba banyak susunan sebelum memilih.",hint:"Sketsa kertas cepat, atau gambar detail?"},
{n:5,type:"mcq",micro:"Jenis prototipe: model fisik",q:"Untuk ide benda (mis. rak, alat bantu), prototipe kasar bisa dibuat dari...",options:["Hanya boleh dibayangkan","Kardus, kertas, lakban, sedotan, plastisin, barang bekas","Bahan asli yang mahal"],answer:1,explain:"Model kardus seukuran asli mengungkap hal yang tidak terlihat di gambar: 'terlalu tinggi', 'sulit dijangkau'.",hint:"Kardus & barang bekas, atau bahan asli mahal?"},
{n:6,type:"mcq",micro:"Jenis prototipe: bermain peran",q:"Untuk ide layanan atau kegiatan (mis. cara menyambut siswa baru), prototipe bisa berupa...",options:["Menulis aturan panjang lalu langsung dijalankan","Tidak bisa diprototipe","Bermain peran: beberapa orang memerankan langkah-langkahnya untuk melihat bagian yang canggung atau membingungkan"],answer:2,explain:"Memerankan alur ('siswa baru datang → disambut siapa → dibawa ke mana') mengungkap celah sebelum hari sungguhan.",hint:"Perankan alurnya, atau langsung jalankan?"},
{n:7,type:"mcq",micro:"Prototipe menjawab pertanyaan",q:"Sebelum membuat prototipe, hal yang perlu jelas:",options:["Pertanyaan apa yang ingin kita jawab dengannya (mis. 'apakah orang mengerti cara memakainya?')","Warna cat yang akan dipakai di versi akhir","Nama merek produk"],answer:0,explain:"Prototipe yang dibuat tanpa pertanyaan jelas menghasilkan 'ya, bagus' yang tidak berguna. Pertanyaan mengarahkan apa yang diperhatikan.",hint:"Pertanyaan yang ingin dijawab, atau warna cat?"},
{n:8,type:"mcq",micro:"Prototipe untuk diperlihatkan",q:"Manfaat menunjukkan prototipe ke orang lain (bukan hanya menyimpannya):",options:["Tidak ada manfaatnya","Mereka bisa mencoba & memberi tahu bagian yang membingungkan atau kurang, yang tidak kita sadari sendiri","Supaya mereka memuji kita"],answer:1,explain:"Pembuat ide punya titik buta. Orang yang baru melihat prototipe menemukan masalah dalam detik-detik pertama.",hint:"Menemukan yang membingungkan, atau mencari pujian?"},
{n:9,type:"order",micro:"Dari ide ke prototipe",q:"Urutkan langkah membuat prototipe pertama sebuah ide.",items:["Tulis ide & satu pertanyaan yang ingin dijawab prototipe ini","Pilih bentuk prototipe termurah yang bisa menjawab pertanyaan itu (sketsa/model/peran)","Buat versi kasarnya dengan bahan seadanya, cepat","Tunjukkan ke beberapa orang, minta mereka mencoba, catat yang kamu pelajari"],answer:[0,1,2,3],explain:"Perjelas pertanyaan → pilih bentuk termurah → buat kasar → uji & pelajari. Bukan 'buat sebagus mungkin lalu pamerkan'.",hint:"Memilih bentuk prototipe sebelum atau sesudah menentukan pertanyaan?"},
{n:10,type:"mcq",micro:"Prototipe tidak harus berfungsi penuh",q:"Prototipe 'aplikasi jadwal' bisa berupa...",options:["Aplikasi asli yang sudah jadi total","Tidak ada, aplikasi harus diprogram dulu","Beberapa kertas bergambar tiap layar; orang 'mengetuk' tombol & kamu ganti kertasnya secara manual"],answer:2,explain:"'Prototipe kertas' menguji apakah alur & tombol masuk akal, tanpa menulis satu baris kode pun.",hint:"Kertas yang diganti manual, atau aplikasi jadi?"},
{n:11,type:"tf",micro:"Prototipe boleh jelek",q:"Benar atau Salah: Prototipe yang terlihat kasar & 'jelek' justru sering lebih berguna daripada yang rapi & indah.",answer:true,explain:"Prototipe kasar mengundang orang jujur mengkritik ('ini kan masih coba-coba'). Yang rapi membuat orang sungkan & sayang diubah.",hint:"Kasar lebih berguna, atau harus rapi?"},
{n:12,type:"tf",micro:"Prototipe = produk akhir?",q:"Benar atau Salah: Prototipe pertama sebaiknya sudah cukup baik untuk langsung dipakai sebagai produk akhir.",answer:false,explain:"Sebaliknya, prototipe pertama hampir selalu berubah banyak setelah diuji. Tujuannya belajar, bukan menghasilkan versi final.",hint:"Langsung jadi produk akhir, atau berubah setelah diuji?"},
{n:13,type:"mcq",micro:"Waktu membuat prototipe",q:"Untuk prototipe pertama, alokasi waktu yang sehat:",options:["Sesingkat mungkin yang masih bisa menjawab pertanyaan, kadang cukup 30 menit","Selama mungkin agar sempurna","Tidak perlu dibatasi"],answer:0,explain:"Semakin cepat prototipe selesai, semakin cepat kita belajar & bisa membuat versi berikutnya yang lebih baik.",hint:"Sesingkat mungkin yang cukup, atau selama mungkin?"},
{n:14,type:"mcq",micro:"Prototipe & bahan bekas",q:"Menggunakan barang bekas untuk prototipe memberi keuntungan:",options:["Tidak ada keuntungan","Murah, cepat didapat, & kita tidak sungkan memotong/mengubahnya","Membuat prototipe terlihat mahal"],answer:1,explain:"Kardus bekas, tutup botol, & kertas koran adalah 'bahan prototipe' yang sempurna: melimpah & bebas dieksperimen.",hint:"Murah & bebas diubah, atau terlihat mahal?"},
{n:15,type:"mcq",micro:"Menunjukkan, bukan menjelaskan",q:"Kelebihan menunjukkan prototipe dibanding hanya menjelaskan ide dengan kata-kata:",options:["Kata-kata selalu lebih jelas","Tidak ada bedanya","Orang bisa langsung bereaksi pada sesuatu yang konkret, komentarnya jadi lebih spesifik & berguna"],answer:2,explain:"'Bagaimana menurutmu tentang ideku?' menghasilkan jawaban samar. 'Coba pakai ini' menghasilkan 'tombol ini terlalu kecil'.",hint:"Reaksi pada yang konkret, atau kata-kata lebih jelas?"},
{n:16,type:"tf",micro:"Prototipe untuk ide non-benda",q:"Benar atau Salah: Ide yang bukan benda (acara, aturan, cara kerja kelompok) tidak bisa diprototipe; hanya benda fisik yang bisa.",answer:false,explain:"Sebaliknya, ide non-benda juga bisa diprototipe dengan mencobanya dalam skala kecil, mis. 'prototipe' aturan piket berupa mencobanya seminggu di satu baris meja dulu, lalu memperbaiki sebelum seluruh kelas.",hint:"Ide non-benda juga bisa diprototipe, atau hanya benda?"},
{n:17,type:"mcq",micro:"Satu prototipe, satu fokus",q:"Prototipe pertama sebaiknya fokus pada...",options:["Satu bagian atau pertanyaan yang paling penting atau paling meragukan","Semua bagian ide sekaligus","Bagian yang paling mudah dibuat saja"],answer:0,explain:"Menguji satu hal dengan jelas mengajari lebih banyak daripada menguji semuanya samar-samar.",hint:"Satu bagian paling penting, atau semua sekaligus?"},
{n:18,type:"mcq",micro:"Prototipe & keberanian mencoba",q:"Membuat prototipe kasar membantu mengatasi rasa takut memulai karena...",options:["Menghilangkan kebutuhan untuk bekerja","Membuat sesuatu yang 'cuma coba-coba' terasa jauh lebih ringan daripada membuat 'karya final'","Membuat kita menunda lebih lama"],answer:1,explain:"'Buat versi jeleknya dulu' melewati kelumpuhan 'harus sempurna'. Kemajuan datang dari mulai, bukan dari menunggu siap.",hint:"Membuat mulai terasa ringan, atau menunda?"},
{n:19,type:"mcq",micro:"Prototipe & tim",q:"Dalam kelompok, membuat prototipe bersama berguna karena...",options:["Hanya satu orang yang perlu paham ide","Membuat kelompok berdebat lebih lama","Semua orang melihat ide yang sama secara konkret, sehingga diskusi jadi tentang hal nyata, bukan bayangan berbeda di kepala masing-masing"],answer:2,explain:"Tanpa prototipe, tiap anggota membayangkan ide sedikit berbeda. Prototipe menyatukan gambaran.",hint:"Menyatukan gambaran, atau memperpanjang perdebatan?"},
{n:20,type:"open",micro:"Rancang prototipe pertama",q:"Pilih satu ide sederhana (mis. 'rak sepatu di depan kelas', 'sistem antre kantin baru', 'permainan untuk mengenal teman baru'). Tulis: (a) satu pertanyaan yang ingin kamu jawab dengan prototipe, (b) bentuk prototipe yang akan kamu buat & bahannya, (c) siapa yang akan mencobanya, (d) apa yang akan kamu perhatikan saat mereka mencoba.",sample:"Ide: permainan untuk mengenal teman baru di minggu pertama. (a) Pertanyaan: apakah permainan ini membuat anak-anak yang belum saling kenal benar-benar berbicara satu sama lain, atau malah hanya yang sudah kenal yang aktif? (b) Bentuk prototipe: kartu-kartu kertas berisi perintah sederhana ('cari 2 orang yang suka makanan sama denganmu', 'temukan seseorang yang lahir di bulan yang sama'), dibuat dari potongan kertas & spidol, sekitar 15 menit. (c) Yang mencoba: 6-8 teman, termasuk 2-3 yang belum saling akrab, dicoba saat istirahat. (d) Yang kuperhatikan: berapa banyak anak yang berbicara dengan orang yang tadinya belum mereka kenal; apakah ada yang bingung dengan perintah kartunya; apakah ada yang berdiri diam tidak ikut; bagian mana yang membuat mereka tertawa atau justru canggung. Setelah itu aku tanya: 'kartu mana yang paling mudah/susah? apa yang bikin kamu ragu ngajak ngobrol?'",explain:"Jawaban baik: pertanyaan yang spesifik & bisa dijawab dengan mengamati (bukan 'apakah ini bagus'), bentuk prototipe yang murah & cepat dengan bahan nyata, penguji yang mencakup target sebenarnya (orang yang belum kenal, bukan hanya teman dekat), & daftar hal konkret yang akan diamati.",hint:"Pertanyaanmu harus sesuatu yang bisa kamu lihat jawabannya dengan mata saat orang mencoba, bukan pendapat mereka saja."},

// FASE B — PEMAHAMAN (21-40): prototipe untuk belajar, versi paling sederhana
{n:21,type:"classify",micro:"Prototipe yang baik vs kurang tepat",q:"Kelompokkan tiap pendekatan ke 'Prototipe yang baik' atau 'Kurang tepat sebagai prototipe'.",items:["Model kardus seukuran asli dibuat dalam sejam untuk mengecek ukuran","Menghabiskan dua minggu mengecat & memoles sebelum ada yang mencoba","Kertas bergambar layar aplikasi yang 'diketuk' & diganti manual","Menunggu sampai semua bahan mahal terkumpul baru mulai membuat"],groups:["Prototipe yang baik","Kurang tepat sebagai prototipe"],answer:{"Prototipe yang baik":["Model kardus seukuran asli dibuat dalam sejam untuk mengecek ukuran","Kertas bergambar layar aplikasi yang 'diketuk' & diganti manual"],"Kurang tepat sebagai prototipe":["Menghabiskan dua minggu mengecat & memoles sebelum ada yang mencoba","Menunggu sampai semua bahan mahal terkumpul baru mulai membuat"]},explain:"Prototipe yang baik: cepat, murah, cukup untuk menjawab pertanyaan. Kurang tepat: lambat, mahal, memoles sebelum belajar.",hint:"Cepat & murah untuk belajar, atau lambat & mahal sebelum belajar?"},
{n:22,type:"mcq",micro:"Prototipe untuk belajar",q:"Tujuan utama prototipe:",options:["Belajar, menemukan apa yang berhasil, apa yang tidak, & apa yang belum kita ketahui","Membuktikan bahwa ide kita pasti benar","Menyelesaikan produk"],answer:0,explain:"Prototipe yang 'gagal' (mengungkap masalah besar) sebenarnya sukses, ia mengajari kita sebelum terlambat.",hint:"Belajar, atau membuktikan kita benar?"},
{n:23,type:"mcq",micro:"Versi paling sederhana (MVP)",q:"'Versi paling sederhana yang masih berguna' dari sebuah ide berarti...",options:["Ide tanpa fitur apa pun","Fitur inti saja yang cukup untuk dipakai & diuji orang, tanpa semua tambahan","Semua fitur sekaligus dari awal"],answer:1,explain:"Membangun inti dulu & mengujinya memberi tahu apakah arah kita benar, sebelum menambah fitur yang mungkin sia-sia.",hint:"Inti saja yang cukup diuji, atau semua fitur?"},
{n:24,type:"mcq",micro:"Fokus pada bagian meragukan",q:"Kalau waktu terbatas, prototipe sebaiknya menguji bagian yang...",options:["Paling mudah & sudah pasti berhasil","Paling tidak penting","Paling tidak pasti, kalau bagian ini gagal, seluruh ide perlu dipikir ulang"],answer:2,explain:"Menguji dulu 'asumsi paling berisiko' memberi informasi terbanyak per usaha. Menguji yang sudah pasti membuang waktu.",hint:"Bagian paling tidak pasti, atau yang sudah pasti?"},
{n:25,type:"mcq",micro:"Prototipe kertas untuk alur",q:"Prototipe kertas cocok untuk menguji...",options:["Apakah urutan langkah & tombol masuk akal bagi pengguna, sebelum membuat versi asli","Apakah warna sudah bagus","Seberapa cepat program berjalan"],answer:0,explain:"Alur & susunan bisa diuji dengan kertas. Kecepatan & warna diuji nanti pada versi yang lebih matang.",hint:"Alur & susunan, atau kecepatan program?"},
{n:26,type:"mcq",micro:"'Wizard of Oz'",q:"Teknik 'Wizard of Oz': prototipe terlihat otomatis, padahal...",options:["Sudah sepenuhnya otomatis","Ada manusia di belakang yang menjalankannya secara manual, untuk menguji apakah idenya berguna sebelum membuat otomatisasinya","Memakai sihir"],answer:1,explain:"Mis. 'asisten pintar' yang jawabannya sebenarnya diketik manusia dari ruang sebelah, menguji apakah orang mau memakainya sebelum membangun sistem sungguhan.",hint:"Manusia menjalankan manual di belakang, atau benar-benar otomatis?"},
{n:27,type:"tf",micro:"Prototipe berulang",q:"Benar atau Salah: Biasanya cukup satu prototipe saja; membuat versi berikutnya hanya pemborosan waktu.",answer:false,explain:"Sebaliknya, biasanya dibutuhkan beberapa prototipe berturut-turut: prototipe 1 → uji → temukan 3 masalah → prototipe 2 memperbaikinya → uji lagi. Versi yang bagus lahir dari putaran ini.",hint:"Beberapa versi berturut-turut, atau sekali jadi?"},
{n:28,type:"tf",micro:"Prototipe harus lengkap?",q:"Benar atau Salah: Sebuah prototipe harus meniru SEMUA bagian ide agar berguna.",answer:false,explain:"Sebaliknya, prototipe yang baik sering hanya meniru satu bagian, bagian yang sedang kita uji. Sisanya bisa 'dipalsukan' atau diabaikan sementara.",hint:"Harus semua bagian, atau cukup bagian yang diuji?"},
{n:29,type:"mcq",micro:"Prototipe & anggaran",q:"Ide bagus tapi mahal untuk dibuat versi aslinya. Prototipe membantu karena...",options:["Membuat ide jadi gratis selamanya","Tidak membantu soal biaya","Menguji apakah ide layak dengan biaya kecil dulu, sebelum memutuskan mengeluarkan biaya besar"],answer:2,explain:"Menghabiskan Rp10.000 untuk prototipe kardus yang mengungkap 'ternyata orang tidak butuh ini' menghemat Rp1.000.000.",hint:"Menguji dengan biaya kecil dulu, atau tidak membantu?"},
{n:30,type:"order",micro:"Menentukan apa yang diprototipe",q:"Urutkan langkah memutuskan bagian mana dari ide yang diprototipe lebih dulu.",items:["Daftar bagian-bagian utama ide & cara kerjanya","Tandai bagian yang paling tidak pasti berhasil","Tandai bagian yang, kalau gagal, membuat seluruh ide tidak berguna","Prototipe bagian yang punya kedua tanda itu lebih dulu"],answer:[0,1,2,3],explain:"Daftar bagian → tandai yang tidak pasti → tandai yang menentukan → prototipe yang paling berisiko & paling menentukan.",hint:"Memprototipe bagian dengan risiko tertinggi lebih dulu atau terakhir?"},
{n:31,type:"mcq",micro:"Prototipe & umpan balik jujur",q:"Cara membuat orang memberi umpan balik jujur pada prototipe:",options:["Katakan 'ini masih versi kasar, tolong kritik sepedasnya, itu yang membantu' & jangan membela tiap komentar","Tunjukkan bahwa kamu sudah kerja keras supaya mereka sungkan mengkritik","Hanya tunjukkan ke orang yang pasti memuji"],answer:0,explain:"Mengizinkan kritik secara eksplisit & tidak membela diri membuat orang berani menyampaikan masalah nyata.",hint:"Undang kritik & jangan membela, atau buat mereka sungkan?"},
{n:32,type:"tf",micro:"Prototipe mengungkap yang tak terduga",q:"Benar atau Salah: Prototipe sering mengungkap masalah atau kebutuhan yang sama sekali tidak terpikir saat ide masih di kepala.",answer:true,explain:"'Ternyata anak kidal kesulitan', 'ternyata orang mengira tombol ini untuk hal lain', temuan seperti ini hampir hanya muncul lewat mencoba benda nyata.",hint:"Mengungkap yang tak terduga, atau hanya membenarkan dugaan?"},
{n:33,type:"mcq",micro:"Storyboard",q:"'Storyboard' sebagai prototipe: serangkaian gambar/kotak yang menunjukkan...",options:["Satu gambar besar tanpa urutan","Bagaimana seseorang memakai ide kita dari awal sampai akhir, langkah demi langkah","Cerita fiksi yang tidak berhubungan"],answer:1,explain:"Storyboard 6 kotak ('Ani lihat masalah → Ani buka alat → Ani lakukan X → hasilnya Y') menguji apakah alur pemakaiannya masuk akal.",hint:"Urutan pemakaian langkah demi langkah, atau satu gambar?"},
{n:34,type:"mcq",micro:"Prototipe yang 'terlalu meyakinkan'",q:"Risiko membuat prototipe yang terlihat sangat jadi & mengilap:",options:["Tidak ada risiko, semakin bagus semakin baik","Prototipe jadi lebih murah","Orang menilai kemasannya, bukan idenya; & mereka sungkan menyarankan perubahan besar"],answer:2,explain:"Prototipe kelewat rapi mengalihkan umpan balik ke hal permukaan & menahan kritik mendasar yang justru paling dibutuhkan.",hint:"Umpan balik jadi soal kemasan & tertahan, atau selalu lebih baik?"},
{n:35,type:"mcq",micro:"Prototipe layanan",q:"Untuk ide 'pojok bantuan PR di perpustakaan', prototipe bisa berupa...",options:["Menjalankannya sungguhan selama 3 hari di satu meja dengan tanda kertas, lalu tanya siapa yang datang & apa yang mereka butuhkan","Menulis proposal lengkap lalu menunggu persetujuan setahun","Membayangkannya saja"],answer:0,explain:"Layanan diprototipe dengan menjalankannya kecil-kecilan & singkat. Kamu belajar kebutuhan nyata yang tidak muncul di proposal.",hint:"Jalankan kecil & singkat, atau proposal panjang?"},
{n:36,type:"mcq",micro:"Prototipe & keputusan lanjut",q:"Setelah menguji prototipe, keputusan yang mungkin:",options:["Selalu hentikan kalau ada satu masalah","Lanjut (arah benar, perbaiki detail), ubah (ada masalah besar, revisi), atau hentikan (ternyata tidak dibutuhkan)","Selalu lanjut apa pun hasilnya"],answer:1,explain:"Prototipe memberi informasi untuk memilih di antara ketiga jalan itu. 'Hentikan' setelah belajar sesuatu bukan kegagalan, itu menghemat usaha.",hint:"Lanjut/ubah/hentikan berdasar hasil, atau selalu satu jalan?"},
{n:37,type:"tf",micro:"Menghentikan ide setelah prototipe",q:"Benar atau Salah: Memutuskan untuk tidak melanjutkan sebuah ide setelah prototipe menunjukkan ide itu tidak dibutuhkan adalah hasil yang buruk & memalukan.",answer:false,explain:"Sebaliknya, itu hasil yang berharga, kamu menghemat berminggu-minggu kerja dengan uji cepat. Belajar 'ini bukan jalannya' adalah kemenangan kecil.",hint:"Memalukan, atau menghemat usaha?"},
{n:38,type:"mcq",micro:"Prototipe & asumsi",q:"Setiap ide punya asumsi tersembunyi ('orang akan mau memakai ini', 'ini muat di tas'). Prototipe berguna untuk...",options:["Menyembunyikan asumsi","Menambah lebih banyak asumsi","Menguji asumsi-asumsi itu terhadap kenyataan, bukan hanya berharap benar"],answer:2,explain:"Menuliskan asumsi & merancang prototipe untuk menguji yang paling berisiko adalah inti kerja yang cerdas.",hint:"Menguji asumsi, atau menyembunyikannya?"},
{n:39,type:"mcq",micro:"Prototipe cepat vs rencana panjang",q:"Untuk ide baru yang belum pernah dicoba siapa pun, mana yang biasanya lebih bijak lebih dulu?",options:["Prototipe kecil & cepat untuk melihat apakah ide dasarnya masuk akal","Rencana tertulis 20 halaman yang sangat rinci","Langsung produksi skala besar"],answer:0,explain:"Rencana rinci untuk ide yang belum teruji sering berdasarkan tebakan. Prototipe menggantikan tebakan dengan bukti sebelum merencanakan detail.",hint:"Prototipe cepat, atau rencana 20 halaman?"},
{n:40,type:"open",micro:"Uji asumsi lewat prototipe",q:"Ide: 'kotak pinjam-alat-tulis' di kelas, siapa saja boleh meminjam pensil/penghapus & mengembalikannya. Tulis: (a) 3 asumsi tersembunyi dari ide ini, (b) untuk asumsi yang paling berisiko, rancang prototipe kecil untuk mengujinya (bentuk, berapa lama, apa yang diamati), (c) berdasarkan kemungkinan hasil, tulis apa yang akan kamu lakukan (lanjut/ubah/hentikan).",sample:"(a) Asumsi tersembunyi: (1) Orang akan mengembalikan alat yang dipinjam, bukan menyimpannya. (2) Cukup banyak orang mau menyumbang alat tulis ke kotak sehingga isinya tidak habis. (3) Orang yang butuh benar-benar akan memakai kotak ini, bukan tetap meminjam langsung ke teman. (b) Asumsi paling berisiko: nomor 1 (alat dikembalikan). Prototipe: sediakan kotak berisi 10 pensil & 5 penghapus bertanda kecil, taruh di meja depan selama satu minggu dengan aturan tertulis singkat & 'papan hitung' (berapa dipinjam, berapa kembali). Yang diamati: jumlah alat yang tersisa tiap sore, apakah orang menulis di papan, komentar teman tentang kenapa lupa/malas mengembalikan. (c) Kemungkinan hasil & tindakan: Jika sebagian besar alat kembali (misal tersisa 12 dari 15 di akhir minggu), LANJUT, tambah isi & buat permanen. Jika separuh hilang, UBAH, coba sistem 'tukar jaminan' (tinggalkan sesuatu saat meminjam) atau kotak dijaga petugas piket, lalu prototipe lagi seminggu. Jika hampir semua hilang & sedikit yang memakai, HENTIKAN bentuk ini, mungkin kebutuhannya kecil atau budaya kelas belum siap; alihkan ke solusi lain seperti 'sudut alat tulis milik guru yang dipinjam dengan mencatat nama'.",explain:"Jawaban baik: 3 asumsi yang memang tersembunyi (bukan hal yang sudah jelas), memilih yang paling berisiko dengan alasan, prototipe kecil & terbatas waktu dengan hal-hal konkret yang diamati (angka lebih baik), & tiga cabang tindakan yang masuk akal sesuai kemungkinan hasil.",hint:"Asumsi paling berisiko biasanya soal perilaku orang ('mereka akan...'), bukan soal apakah kotaknya bisa dibuat."},

// FASE C — PENERAPAN (41-60): teknik membuat prototipe
{n:41,type:"mcq",micro:"Prototipe skala",q:"Untuk ide besar (mis. 'taman baca di sudut sekolah'), prototipe berskala berarti...",options:["Hanya membuat gambar rencana besar","Buat versi mini dulu: satu rak, satu karpet, di satu sudut kecil, jalankan sebulan","Bangun seluruhnya langsung"],answer:1,explain:"Versi mini menguji apakah siswa benar-benar datang & membaca, dengan risiko & biaya kecil sebelum memperbesar.",hint:"Versi mini dulu, atau bangun seluruhnya?"},
{n:42,type:"mcq",micro:"Prototipe cepat: batas waktu",q:"Menetapkan 'prototipe harus selesai dalam 1 jam' memaksa kita...",options:["Membuat sesuatu yang tidak berguna","Menyerah sebelum mulai","Memilih bentuk paling sederhana & fokus pada inti, bukan menghias"],answer:2,explain:"Batas waktu ketat adalah teman prototipe: ia mencegah kita tenggelam dalam kerapian & mempercepat pembelajaran.",hint:"Fokus pada inti, atau membuat yang tak berguna?"},
{n:43,type:"mcq",micro:"Prototipe & 'pengguna sungguhan'",q:"Menguji prototipe dengan calon pengguna sebenarnya (bukan hanya teman dekat) penting karena...",options:["Teman dekat cenderung memuji & memakai ide 'sesuai maksud kita'; pengguna baru menunjukkan kebingungan nyata","Teman dekat lebih pintar","Tidak ada bedanya"],answer:0,explain:"Orang yang tidak tahu 'maksudmu' bereaksi seperti pengguna sungguhan nanti, itulah umpan balik yang berharga.",hint:"Pengguna baru menunjukkan kebingungan nyata, atau teman dekat lebih baik?"},
{n:44,type:"mcq",micro:"Mengamati, bukan hanya bertanya",q:"Saat orang mencoba prototipemu, yang paling berharga adalah...",options:["Menjelaskan terus cara memakainya","Mengamati apa yang mereka LAKUKAN (di mana ragu, salah pencet, berhenti), bukan hanya mendengar pendapat mereka","Hanya menanyakan 'suka atau tidak?'"],answer:1,explain:"Orang sering berkata 'bagus' tapi tindakannya menunjukkan kebingungan. Perilaku lebih jujur daripada kata-kata sopan.",hint:"Amati tindakan, atau tanya 'suka atau tidak'?"},
{n:45,type:"tf",micro:"Diam saat orang mencoba",q:"Benar atau Salah: Saat seseorang mencoba prototipemu, sebaiknya kamu diam & tidak membantu, supaya terlihat bagian mana yang membingungkan tanpa panduanmu.",answer:true,explain:"Kalau kamu terus menuntun, kamu menguji 'seberapa baik kamu menjelaskan', bukan 'seberapa jelas prototipenya'. Menahan diri mengungkap masalah nyata.",hint:"Diam & amati, atau terus membantu?"},
{n:46,type:"mcq",micro:"Prototipe 'salah sengaja'",q:"Kadang berguna membuat dua prototipe berbeda (A & B) & membandingkannya karena...",options:["Membuat dua kali lebih lama selalu lebih baik","Supaya salah satu pasti dipuji","Orang lebih mudah berkata 'aku lebih suka A karena...' daripada menilai satu prototipe sendirian"],answer:2,explain:"Perbandingan mengeluarkan alasan & preferensi yang tidak muncul saat orang hanya melihat satu pilihan.",hint:"Perbandingan memancing alasan, atau sekadar lebih lama?"},
{n:47,type:"mcq",micro:"Prototipe aturan/kegiatan",q:"Cara memprototipe 'aturan diskusi kelas yang baru':",options:["Coba aturan itu di satu sesi diskusi pendek, minta pendapat setelahnya, perbaiki sebelum dipakai permanen","Umumkan sebagai aturan tetap langsung","Tulis di dinding tanpa pernah mencoba"],answer:0,explain:"Menjalankan aturan sekali dalam skala kecil mengungkap bagian yang tidak praktis sebelum semua orang terikat padanya.",hint:"Coba sekali & perbaiki, atau langsung permanen?"},
{n:48,type:"mcq",micro:"Bahan prototipe digital",q:"Untuk prototipe tampilan aplikasi/situs tanpa memprogram, bisa pakai...",options:["Tidak mungkin","Kertas & spidol, atau menyusun kotak & teks di aplikasi presentasi/gambar sederhana","Harus belajar bahasa pemrograman dulu"],answer:1,explain:"'Mockup' dari potongan gambar & teks sudah cukup untuk menguji apakah susunan & alurnya masuk akal.",hint:"Kertas / kotak sederhana, atau harus memprogram?"},
{n:49,type:"mcq",micro:"Prototipe & pertanyaan setelah mencoba",q:"Pertanyaan yang baik ditanyakan setelah orang mencoba prototipe:",options:["'Bagus kan?'","'Kamu tidak menemukan masalah, kan?'","'Bagian mana yang membingungkan? Apa yang kamu harapkan terjadi tapi tidak? Kapan kamu akan benar-benar memakai ini?'"],answer:2,explain:"Pertanyaan terbuka & spesifik menggali informasi; pertanyaan yang mengarahkan ke jawaban 'ya' menyembunyikannya.",hint:"Terbuka & spesifik, atau mengarahkan ke 'ya'?"},
{n:50,type:"order",micro:"Sesi uji prototipe",q:"Urutkan langkah sesi menguji prototipe dengan satu orang.",items:["Jelaskan singkat: 'ini versi kasar, aku ingin belajar, bukan cari pujian'","Beri tugas nyata ('coba pakai ini untuk melakukan X') lalu diam & amati","Setelah selesai, tanyakan bagian yang membingungkan & yang diharapkan berbeda","Catat temuan; ulangi dengan 2-3 orang lain sebelum menyimpulkan"],answer:[0,1,2,3],explain:"Bingkai → beri tugas & amati diam → tanya sesudah → ulangi & simpulkan. Satu orang belum cukup untuk pola.",hint:"Bertanya detail dilakukan sebelum atau sesudah mengamati mereka mencoba?"},
{n:51,type:"mcq",micro:"Menguji dengan sedikit orang",q:"Berapa orang biasanya cukup untuk menemukan sebagian besar masalah besar pada prototipe kasar?",options:["Sekitar 3-5 orang sudah menunjukkan pola masalah utama","Minimal 100 orang","Cukup 1 orang saja selalu"],answer:0,explain:"Untuk prototipe awal, 3-5 penguji sudah mengungkap masalah yang berulang. Uji besar berguna nanti pada versi matang.",hint:"3-5 orang, atau harus ratusan?"},
{n:52,type:"tf",micro:"Prototipe menghemat perdebatan",q:"Benar atau Salah: Membuat prototipe tidak ada hubungannya dengan perdebatan kelompok & tidak membantu menyelesaikan adu pendapat.",answer:false,explain:"Sebaliknya, 'ayo kita buat kasarnya & coba' mengubah adu pendapat jadi bukti. Sering satu uji 20 menit mengakhiri debat sejam.",hint:"Mengubah debat jadi bukti, atau memperpanjang?"},
{n:53,type:"mcq",micro:"Prototipe & catatan",q:"Selama menguji prototipe, penting mencatat...",options:["Tidak perlu mencatat","Apa yang terjadi (tindakan, kebingungan, komentar) secepat mungkin, sebelum lupa atau tercampur ingatan","Hanya kesan umum di akhir hari"],answer:1,explain:"Detail hilang cepat. Catatan langsung ('penguji 2 mencoba menarik, padahal harus didorong') adalah bahan perbaikan.",hint:"Catat detail segera, atau kesan umum saja?"},
{n:54,type:"mcq",micro:"Prototipe berbiaya nol",q:"Sebelum membuat apa pun, 'prototipe pikiran' sederhana:",options:["Tidak ada, harus langsung membuat","Membayangkannya sendiri tanpa menceritakan","Ceritakan langkah demi langkah bagaimana seseorang akan memakai ide ini, ke teman, & lihat di mana ceritanya tersendat"],answer:2,explain:"Menceritakan alur dengan lantang ke orang lain sering langsung mengungkap 'tunggu, di langkah ini bagaimana?'.",hint:"Ceritakan alur ke orang, atau langsung membuat?"},
{n:55,type:"mcq",micro:"Prototipe & bagian yang dipalsukan",q:"Dalam prototipe, 'memalsukan' bagian yang belum penting diuji berarti...",options:["Menggantinya dengan sesuatu yang sederhana (mis. hasil ditulis manual, gambar tempelan) supaya fokus tetap di bagian yang diuji","Berbohong pada penguji tentang tujuan","Membuat semuanya palsu"],answer:0,explain:"Mis. menguji alur pemesanan tanpa sistem pembayaran sungguhan, cukup tulis 'pembayaran berhasil' di kertas. Fokus tetap di alur.",hint:"Sederhanakan bagian yang belum diuji, atau berbohong ke penguji?"},
{n:56,type:"tf",micro:"Prototipe & rasa memiliki",q:"Benar atau Salah: Melihat & memegang prototipe sering membuat orang (termasuk pembuat keputusan) lebih memahami & mendukung sebuah ide dibanding hanya membaca penjelasannya.",answer:true,explain:"Sesuatu yang konkret & bisa dipegang terasa nyata & mungkin. Prototipe adalah alat meyakinkan sekaligus alat belajar.",hint:"Prototipe membantu orang memahami & mendukung, atau tidak berpengaruh?"},
{n:57,type:"mcq",micro:"Menyusun temuan prototipe",q:"Setelah menguji prototipe ke 4 orang, cara mengolah temuan:",options:["Abaikan semua & lanjutkan rencana semula","Kelompokkan masalah yang muncul, prioritaskan yang dialami banyak orang & yang paling menghambat","Perbaiki setiap komentar satu per satu tanpa memilah"],answer:1,explain:"Masalah yang dialami 3 dari 4 penguji lebih penting daripada satu keluhan unik. Prioritaskan pola.",hint:"Kelompokkan & prioritaskan pola, atau ikuti setiap komentar / abaikan?"},
{n:58,type:"mcq",micro:"Prototipe berikutnya",q:"Prototipe versi kedua sebaiknya...",options:["Sudah menjadi produk final yang rapi","Mengabaikan temuan versi pertama","Memperbaiki 2-3 masalah terpenting dari versi pertama, lalu diuji lagi, tetap kasar"],answer:2,explain:"Perbaiki yang paling penting, uji lagi, ulangi. Kerapian datang belakangan, setelah arah & bentuk mantap.",hint:"Perbaiki beberapa hal penting & uji lagi, atau langsung final?"},
{n:59,type:"mcq",micro:"Prototipe & tenggat",q:"Kelompokmu punya 2 minggu untuk proyek. Kapan sebaiknya prototipe pertama selesai?",options:["Dalam beberapa hari pertama, supaya ada waktu menguji & memperbaiki minimal sekali","Di hari terakhir","Tidak perlu prototipe kalau ada tenggat"],answer:0,explain:"Prototipe di awal memberi ruang untuk putaran perbaikan. Prototipe di akhir tidak sempat mengajari apa pun.",hint:"Beberapa hari pertama, atau hari terakhir?"},
{n:60,type:"open",micro:"Buat & uji (rencana rinci)",q:"Pilih satu ide. Buat rencana prototipe yang bisa kamu jalankan minggu ini: (a) pertanyaan utama, (b) bentuk prototipe + bahan + perkiraan waktu membuat, (c) 3 pengguna yang akan mencoba & tugas yang kamu berikan ke mereka, (d) 4 hal yang akan kamu amati, (e) bagaimana kamu akan mencatat temuan.",sample:"Ide: 'papan tukar buku' di kelas, siswa menaruh buku yang sudah dibaca & mengambil punya orang lain. (a) Pertanyaan utama: apakah siswa mau menaruh bukunya sendiri (memberi lebih dulu), atau semua ingin mengambil tapi tidak ada yang menaruh? (b) Bentuk prototipe: satu rak kardus dua tingkat berlabel 'Ambil' & 'Taruh di sini', plus buku catatan sederhana. Bahan: kardus, spidol, lakban, buku tulis bekas. Waktu membuat: sekitar 45 menit. (c) Tiga pengguna: dua teman yang suka membaca & satu yang jarang membaca. Tugas: 'anggap kamu punya buku yang sudah selesai kamu baca di rumah, tunjukkan apa yang akan kamu lakukan dengan rak ini besok; lalu cari buku yang mau kamu bawa pulang.' (d) Yang diamati: (1) apakah mereka ragu menaruh buku bagus mereka; (2) apakah mereka bisa menemukan buku yang menarik atau bilang 'tidak ada yang mau'; (3) apakah mereka menulis di buku catatan tanpa disuruh; (4) berapa lama mereka berdiri di depan rak sebelum memutuskan. (e) Mencatat: aku bawa kertas & langsung menulis kutipan kata mereka + apa yang mereka lakukan, satu baris per kejadian, dan setelah ketiganya selesai aku rangkum pola dalam 5 menit.",explain:"Jawaban baik: pertanyaan yang menyasar asumsi perilaku (bukan 'apakah rak bagus'), prototipe murah dengan waktu realistis, penguji yang mencakup ragam target termasuk yang bukan penggemar, tugas yang menyerupai pemakaian nyata, 4 hal amatan yang konkret & bisa dilihat, & cara mencatat yang praktis.",hint:"Tugas untuk penguji harus berupa 'lakukan X', bukan 'lihat ini dan beri pendapat'."},

// FASE D — PENALARAN (61-80): apa yang diuji, jangan jatuh cinta, membaca hasil
{n:61,type:"mcq",micro:"Prototipe menguji ide, bukan orang",q:"Kalau penguji kebingungan memakai prototipe, kesimpulan yang tepat:",options:["Prototipenya sudah sempurna, abaikan","Prototipenya belum cukup jelas, itu informasi untuk memperbaiki, bukan tanda penggunanya 'kurang pintar'","Penggunanya memang tidak mampu"],answer:1,explain:"Kalau pengguna sungguhan nanti akan sama bingungnya, lebih baik tahu sekarang. Salahkan desain, bukan orang.",hint:"Desain perlu diperbaiki, atau pengguna kurang mampu?"},
{n:62,type:"mcq",micro:"Jangan jatuh cinta pada prototipe",q:"Bahaya terlalu menyayangi prototipe yang sudah kamu buat:",options:["Tidak ada bahaya","Prototipe jadi lebih kuat","Kamu jadi enggan mengubahnya banyak meski temuan menunjukkan perlu, & mengabaikan kritik"],answer:2,explain:"Prototipe adalah alat sekali pakai untuk belajar. Kesiapan membuang & membuat ulang adalah tanda sikap yang sehat.",hint:"Enggan mengubah & mengabaikan kritik, atau tidak ada bahaya?"},
{n:63,type:"mcq",micro:"Prototipe yang menjawab pertanyaan salah",q:"Kamu ingin tahu 'apakah orang mau memakai ini', tapi prototipemu hanya menguji 'apakah warnanya bagus'. Masalahnya:",options:["Prototipe tidak dirancang untuk menjawab pertanyaan yang paling penting, perlu diubah agar menguji kemauan pakai","Tidak masalah, warna juga penting","Berarti idenya gagal"],answer:0,explain:"Prototipe harus disesuaikan dengan pertanyaan. Menguji hal yang mudah alih-alih hal yang penting adalah jebakan umum.",hint:"Ubah agar menguji yang penting, atau warna sudah cukup?"},
{n:64,type:"tf",micro:"Hasil prototipe bisa mengejutkan",q:"Benar atau Salah: Prototipe tidak pernah mengubah pemahaman kita tentang masalah; ia hanya menguji solusi.",answer:false,explain:"Sebaliknya, menguji dengan pengguna nyata bisa mengungkap 'sebenarnya yang menyulitkan kami bukan ini, tapi itu'. Temuan ini sangat berharga & menghemat usaha yang salah arah.",hint:"Bisa mengungkap masalah sebenarnya berbeda, atau selalu sesuai dugaan?"},
{n:65,type:"mcq",micro:"Prototipe & bukti vs harapan",q:"Setelah menguji, kamu mendapat 3 sinyal negatif & 1 positif, tapi kamu sangat berharap ide ini berhasil. Sikap jujur:",options:["Ulangi uji sampai dapat hasil yang diinginkan","Akui pola negatifnya, cari tahu penyebabnya, & pertimbangkan mengubah ide, jangan hanya berpegang pada 1 sinyal positif","Fokus pada yang 1 positif & abaikan sisanya"],answer:1,explain:"Menyaring bukti agar sesuai harapan (bias) membuat prototipe sia-sia. Dengarkan pola, bukan hanya bagian yang menyenangkan.",hint:"Dengarkan pola negatif, atau berpegang pada 1 sinyal positif?"},
{n:66,type:"mcq",micro:"Berapa banyak perbaikan per putaran",q:"Antar putaran prototipe, sebaiknya mengubah...",options:["Semua hal sekaligus","Tidak mengubah apa pun","Beberapa hal terpenting saja, supaya kamu tahu perubahan mana yang membuat perbedaan"],answer:2,explain:"Kalau mengubah 10 hal sekaligus & hasilnya membaik, kamu tidak tahu perubahan mana yang berjasa. Ubah sedikit, uji, pelajari.",hint:"Beberapa hal terpenting, atau semua sekaligus?"},
{n:67,type:"mcq",micro:"Prototipe & realitas produksi",q:"Prototipe kardus berhasil. Sebelum membuat versi asli, yang perlu dipikir:",options:["Apakah bentuk & ukuran yang berhasil di kardus masih masuk akal dengan bahan asli, biaya, & cara pembuatannya","Tidak ada, langsung salin persis","Buat versi asli 10x lebih besar"],answer:0,explain:"Beberapa hal yang mudah di kardus (menekuk, memotong) sulit di bahan asli. Prototipe menjawab 'apakah idenya benar', bukan semua detail produksi.",hint:"Cek kelayakan dengan bahan asli, atau salin persis?"},
{n:68,type:"mcq",micro:"Prototipe & etika",q:"Saat menguji prototipe layanan dengan orang sungguhan, hal yang perlu dijaga:",options:["Buat mereka bergantung supaya idenya terlihat sukses","Jujur bahwa ini uji coba, jangan membuat mereka mengandalkan sesuatu yang belum tentu berlanjut, & hargai waktu mereka","Rahasiakan bahwa ini prototipe agar reaksinya alami"],answer:1,explain:"Menguji dengan orang berarti bertanggung jawab pada mereka: kejujuran tentang statusnya & tidak merugikan mereka.",hint:"Jujur & tidak merugikan penguji, atau rahasiakan & buat bergantung?"},
{n:69,type:"mcq",micro:"Kapan berhenti membuat prototipe",q:"Kamu berhenti membuat prototipe & mulai membangun versi sungguhan ketika...",options:["Setelah tepat satu prototipe, selalu","Tidak pernah, terus prototipe selamanya","Beberapa putaran uji sudah tidak lagi mengungkap masalah besar baru & arahnya jelas"],answer:2,explain:"Ketika prototipe berhenti mengajari hal baru yang penting, uangmu lebih baik dipakai membangun yang sebenarnya.",hint:"Saat tidak ada masalah besar baru, atau setelah tepat satu?"},
{n:70,type:"tf",micro:"Prototipe & rencana bisa berubah",q:"Benar atau Salah: Rencana proyek yang baik memberi ruang bagi kemungkinan bahwa prototipe akan mengubah arah ide secara signifikan.",answer:true,explain:"Kalau rencana menganggap ide sudah pasti benar & prototipe hanya formalitas, kita mengabaikan tujuan prototipe. Rencana yang baik menyisakan titik keputusan setelah uji.",hint:"Beri ruang untuk perubahan arah, atau anggap ide sudah pasti?"},
{n:71,type:"mcq",micro:"Prototipe untuk meyakinkan vs untuk belajar",q:"Kalau kamu membuat prototipe HANYA untuk meyakinkan guru/kepala sekolah menyetujui ide, risikonya:",options:["Kamu mungkin menyembunyikan atau tidak menguji kelemahan nyata, sehingga masalah baru muncul saat dijalankan sungguhan","Tidak ada risiko","Ide jadi otomatis lebih baik"],answer:0,explain:"Prototipe yang jujur menguji kelemahan; prototipe 'jualan' menyembunyikannya. Yang kedua menunda masalah, tidak menghapusnya.",hint:"Bisa menyembunyikan kelemahan, atau selalu aman?"},
{n:72,type:"mcq",micro:"Membaca 'ketiadaan minat'",q:"Kamu menawarkan prototipe layanan gratis & hampir tidak ada yang datang mencoba. Kemungkinan artinya:",options:["Uji coba selalu sepi, abaikan","Kebutuhan akan layanan ini mungkin lebih kecil dari dugaan, atau cara menawarkannya belum tepat, keduanya perlu diselidiki","Orang-orang malas & idenya tetap bagus"],answer:1,explain:"Ketiadaan minat adalah data. Bisa jadi masalah kebutuhan, bisa jadi masalah promosi/akses, jangan langsung menyalahkan salah satu.",hint:"Selidiki kebutuhan & cara menawarkan, atau salahkan orang malas?"},
{n:73,type:"mcq",micro:"Prototipe & keberagaman penguji",q:"Menguji prototipe alat tulis hanya dengan siswa yang tidak kidal berisiko...",options:["Tidak berisiko, kidal jarang","Membuat uji lebih akurat","Melewatkan masalah yang dialami siswa kidal, yang baru muncul saat produk dipakai luas"],answer:2,explain:"Penguji yang beragam (kidal, tinggi/pendek, cepat/lambat) menemukan masalah yang tidak muncul pada kelompok seragam.",hint:"Bisa melewatkan masalah kelompok tertentu, atau lebih akurat?"},
{n:74,type:"mcq",micro:"Prototipe yang 'terlalu berhasil'",q:"Semua penguji memuji prototipe & tidak menemukan satu masalah pun. Sikap waspada:",options:["Cek: apakah mereka sungkan mengkritik? apakah tugasnya terlalu mudah? coba tugas lebih menantang atau penguji yang lebih kritis","Rayakan, ide sudah sempurna","Langsung produksi massal"],answer:0,explain:"Prototipe kasar hampir selalu punya masalah. 'Semua sempurna' sering berarti umpan baliknya belum jujur atau ujinya belum cukup dalam.",hint:"Curigai umpan balik yang terlalu mulus, atau langsung rayakan?"},
{n:75,type:"order",micro:"Dari uji prototipe ke keputusan",q:"Urutkan langkah menutup satu putaran prototipe.",items:["Kumpulkan semua catatan dari sesi-sesi uji","Kelompokkan temuan: masalah yang berulang, kejutan, & hal yang berhasil","Putuskan: lanjut & perbaiki detail / ubah bagian besar / hentikan ide","Bila lanjut/ubah: pilih 2-3 perbaikan untuk prototipe berikutnya"],answer:[0,1,2,3],explain:"Kumpulkan → kelompokkan → putuskan arah → pilih perbaikan berikutnya. Keputusan berdasar pola temuan, bukan kesan.",hint:"Memutuskan arah sebelum atau sesudah mengelompokkan temuan?"},
{n:76,type:"tf",micro:"Prototipe hemat waktu keseluruhan",q:"Benar atau Salah: Membuat prototipe selalu menambah waktu total proyek tanpa manfaat yang sepadan.",answer:false,explain:"Sebaliknya, meski membuat prototipe butuh waktu di awal, biasanya ini menghemat waktu total: beberapa jam membuat prototipe bisa mencegah berminggu-minggu membangun sesuatu yang ternyata tidak dipakai atau salah bentuk.",hint:"Menghemat waktu total, atau selalu memperlambat?"},
{n:77,type:"mcq",micro:"Prototipe & kegagalan yang aman",q:"Nilai penting prototipe bagi keberanian berinovasi:",options:["Menghilangkan kebutuhan mencoba","Membuat 'gagal' jadi murah & cepat, sehingga kita berani mencoba ide yang belum tentu berhasil","Menjamin tidak akan pernah gagal"],answer:1,explain:"Kalau setiap ide harus langsung dibuat penuh, kita hanya berani mencoba yang 'aman'. Prototipe membuka ruang untuk ide berani.",hint:"Membuat gagal jadi murah, atau menjamin tidak gagal?"},
{n:78,type:"mcq",micro:"Prototipe & komunikasi ke tim",q:"Setelah menguji prototipe, cara berbagi temuan ke kelompok:",options:["Sampaikan kesimpulanmu tanpa data","Simpan temuan untuk diri sendiri","Tunjukkan bukti konkret ('3 dari 4 penguji mencoba menarik bagian ini'), bukan hanya pendapat ('menurutku perlu diubah')"],answer:2,explain:"Temuan berbasis pengamatan nyata lebih meyakinkan & lebih adil didiskusikan daripada opini pribadi.",hint:"Bukti konkret dari pengamatan, atau pendapat pribadi?"},
{n:79,type:"mcq",micro:"Menyeimbangkan prototipe & pelaksanaan",q:"Godaan yang perlu dihindari terkait prototipe:",options:["Terus membuat prototipe demi prototipe tanpa pernah berkomitmen membangun & menjalankan versi sungguhan","Membuat satu prototipe lalu menguji","Memperbaiki berdasarkan temuan"],answer:0,explain:"Prototipe tanpa akhir bisa jadi cara menghindari risiko benar-benar meluncurkan sesuatu. Kenali kapan sudah cukup belajar.",hint:"Prototipe tanpa henti tanpa komitmen, atau menguji & memperbaiki?"},
{n:80,type:"open",micro:"Membaca hasil yang bertentangan",q:"Kamu menguji prototipe 'jadwal belajar visual' ke 5 teman. Hasil: 3 orang bilang sangat membantu & langsung mengerti; 2 orang bingung & bilang 'lebih ribet dari tulis biasa'. Analisis: (a) apa saja kemungkinan penyebab perbedaan ini, (b) uji tambahan apa yang akan kamu lakukan untuk memahaminya, (c) keputusan sementara kamu & alasannya.",sample:"(a) Kemungkinan penyebab: (1) Dua orang yang bingung mungkin sudah punya sistem sendiri yang mereka sukai, jadi apa pun yang baru terasa 'lebih ribet'. (2) Prototipe mungkin kurang jelas untuk orang yang tidak terbiasa berpikir visual, butuh contoh terisi, bukan template kosong. (3) Ketiga yang suka mungkin memang tipe yang terbantu gambar/warna, sementara dua lainnya lebih nyaman dengan teks, jadi idenya cocok untuk sebagian orang, bukan semua. (4) Bisa jadi tugas yang kuberikan berbeda tingkat kesulitannya. (b) Uji tambahan: (i) Tanya kelima orang bagaimana biasanya mereka mengatur jadwal sekarang, untuk melihat apakah yang bingung memang sudah punya kebiasaan kuat. (ii) Buat versi kedua dengan satu contoh yang sudah terisi penuh sebagai panduan, lalu uji ke 3 orang baru yang belum pernah lihat. (iii) Minta dua yang bingung mencoba lagi versi baru itu & lihat apakah kebingungannya berkurang. (c) Keputusan sementara: LANJUT tapi UBAH, aku akan menambahkan contoh terisi & petunjuk singkat, lalu menguji lagi. Alasannya: sinyalnya condong positif (3 dari 5, dan mereka 'langsung mengerti'), kebingungan 2 orang tampak berkaitan dengan kurangnya contoh & kebiasaan lama, bukan cacat mendasar. Tapi aku akan menerima kalau ternyata alat ini memang hanya cocok untuk sebagian orang, dan itu tidak apa-apa selama dijadikan pilihan, bukan kewajiban.",explain:"Jawaban baik: beberapa hipotesis penyebab yang berbeda (bukan hanya satu), rencana uji tambahan yang spesifik untuk memilah di antara hipotesis itu, & keputusan sementara yang jujur mempertimbangkan bahwa idenya mungkin cocok untuk sebagian orang saja, bukan memaksakan 'harus berhasil untuk semua'.",hint:"Jangan langsung menyimpulkan 'yang bingung salah' atau 'ide gagal', daftar beberapa kemungkinan lalu rancang cara membedakannya."},

// FASE E — TANTANGAN (81-100): skenario & kapstone
{n:81,type:"mcq",micro:"Skenario: waktu sangat sempit",q:"Proyek harus dikumpulkan 3 hari lagi & belum ada prototipe. Langkah terbaik hari ini:",options:["Panik & kerjakan semua bagian sekaligus","Buat prototipe paling kasar dalam 1-2 jam untuk menguji bagian paling berisiko, lalu perbaiki besok","Lewati prototipe, langsung buat versi final"],answer:1,explain:"Bahkan uji cepat 1 jam bisa mencegah kesalahan besar. Sedikit prototipe selalu lebih baik daripada nol.",hint:"Prototipe kasar cepat untuk bagian berisiko, atau lewati?"},
{n:82,type:"mcq",micro:"Skenario: guru minta versi rapi",q:"Guru meminta 'prototipe yang bagus' untuk dinilai, tapi kamu tahu versi kasar lebih baik untuk belajar. Sikap yang seimbang:",options:["Langsung buat yang rapi & lewati uji","Menolak membuat apa pun yang rapi","Buat prototipe kasar untuk menguji & belajar dulu, lalu rapikan secukupnya untuk presentasi setelah temuan masuk"],answer:2,explain:"Dua tujuan (belajar & menunjukkan) bisa dipenuhi berurutan: uji dulu dengan kasar, poles seperlunya di akhir.",hint:"Kasar dulu untuk belajar lalu rapikan, atau langsung rapi?"},
{n:83,type:"mcq",micro:"Skenario: tidak ada bahan",q:"Kamu ingin memprototipe ide benda tapi tidak punya bahan sama sekali. Alternatif:",options:["Gambar sketsa berskala, buat storyboard pemakaian, atau perankan cara memakainya dengan tangan kosong","Menyerah sampai punya bahan","Membayangkannya sendiri saja"],answer:0,explain:"Sketsa, storyboard, & bermain peran adalah prototipe berbiaya nol yang tetap menguji alur & kegunaan.",hint:"Sketsa / storyboard / peran, atau menyerah?"},
{n:84,type:"mcq",micro:"Skenario: penguji memberi ide baru",q:"Saat menguji, seorang penguji mengusulkan fitur tambahan yang menarik. Sikap yang tepat:",options:["Abaikan sepenuhnya","Catat sebagai kemungkinan, tapi jangan langsung menambahnya, selesaikan dulu menguji pertanyaan awal","Langsung tambahkan fitur itu ke prototipe saat itu juga"],answer:1,explain:"Ide dari penguji berharga tapi bisa mengalihkan fokus uji. Kumpulkan, pertimbangkan setelah putaran ini selesai.",hint:"Catat untuk nanti, atau langsung tambah / abaikan?"},
{n:85,type:"tf",micro:"Prototipe pertama pasti berubah",q:"Benar atau Salah: Wajar & sehat bila prototipe akhir sangat berbeda dari prototipe pertama, itu tanda kamu belajar dari tiap putaran.",answer:true,explain:"Kalau versi final identik dengan draf pertama, kemungkinan besar umpan balik tidak benar-benar dipakai.",hint:"Perbedaan besar antar versi itu sehat, atau tanda gagal?"},
{n:86,type:"mcq",micro:"Skenario: kelompok berdebat tanpa henti",q:"Kelompokmu sudah 40 menit berdebat tentang bentuk ide tanpa kesepakatan. Usul yang membuka jalan:",options:["Terus berdebat sampai satu pihak menyerah","Voting cepat tanpa mencoba apa pun","'Ayo kita buat dua prototipe kasar dari dua usulan ini dalam 20 menit & coba, biar kelihatan mana yang lebih jalan'"],answer:2,explain:"Prototipe mengubah perdebatan pendapat jadi perbandingan bukti. Sering ini cara tercepat keluar dari kebuntuan.",hint:"Buat & bandingkan prototipe, atau terus berdebat?"},
{n:87,type:"mcq",micro:"Skenario: prototipe mahal terlanjur dibuat",q:"Kamu terlanjur menghabiskan banyak waktu & bahan membuat prototipe yang rapi, lalu uji menunjukkan bentuknya salah. Sikap:",options:["Terima temuannya & buat versi baru, waktu yang lalu adalah pelajaran, bukan alasan mempertahankan bentuk yang salah","Pertahankan bentuk itu karena sayang usaha yang sudah keluar","Sembunyikan hasil uji"],answer:0,explain:"'Biaya yang sudah keluar' tidak boleh menyandera keputusan. Yang penting: apa langkah terbaik dari titik ini ke depan.",hint:"Ikuti temuan & buat ulang, atau pertahankan karena sayang usaha?"},
{n:88,type:"mcq",micro:"Skenario: memprototipe ide sosial",q:"Ide: 'sistem teman bercerita' agar tidak ada siswa yang sendirian saat istirahat. Prototipe yang tepat:",options:["Buat aturan tertulis panjang tanpa mencoba","Coba selama seminggu dengan sekelompok kecil sukarelawan, amati apakah membantu & apa yang canggung, tanya perasaan peserta","Umumkan ke seluruh sekolah sebagai program resmi langsung"],answer:1,explain:"Ide yang menyangkut perasaan & hubungan perlu diuji lembut dalam skala kecil, dengan memperhatikan dampak pada peserta.",hint:"Coba kecil dengan sukarelawan & amati, atau umumkan resmi langsung?"},
{n:89,type:"mcq",micro:"Skenario: hasil prototipe tidak disukai kelompok",q:"Prototipe menunjukkan ide favorit kelompok tidak berjalan baik, tapi anggota tidak mau menerimanya. Sikap yang bertanggung jawab:",options:["Diamkan temuan agar tidak ada yang kecewa","Paksakan idenya tetap dijalankan","Tunjukkan bukti pengamatan dengan tenang, akui kekecewaan bersama, & ajak memikirkan perbaikan atau arah baru berdasarkan temuan"],answer:2,explain:"Prototipe berguna hanya kalau temuannya dipakai. Menyembunyikan hasil buruk demi perasaan hanya menunda kekecewaan yang lebih besar.",hint:"Tunjukkan bukti & cari perbaikan, atau diamkan / paksakan?"},
{n:90,type:"order",micro:"Proyek: siklus prototipe seminggu",q:"Urutkan langkah proyek 'kembangkan satu ide lewat siklus prototipe' dalam seminggu.",items:["Hari 1: perjelas ide & pertanyaan utama, buat prototipe kasar pertama","Hari 2: uji ke 3-5 orang, catat temuan","Hari 3: kelompokkan temuan, buat prototipe kedua yang memperbaiki 2-3 hal","Hari 4-5: uji lagi, putuskan (lanjut/ubah/hentikan), siapkan versi untuk dipakai atau laporan temuan"],answer:[0,1,2,3],explain:"Buat → uji → perbaiki → uji lagi → putuskan. Minimal dua putaran dalam seminggu jauh lebih berharga daripada satu prototipe besar di akhir.",hint:"Membuat prototipe kedua sebelum atau sesudah mengelompokkan temuan pertama?"},
{n:91,type:"mcq",micro:"Skenario: idemu terbukti tidak dibutuhkan",q:"Setelah dua putaran, prototipe jelas menunjukkan tidak ada yang membutuhkan idemu. Yang kamu tulis di laporan:",options:["Apa yang kamu uji, bagaimana, temuan yang menunjukkan ketiadaan kebutuhan, & pelajaran untuk ide berikutnya","Bahwa proyek gagal & kamu tidak belajar apa-apa","Data yang dipoles agar terlihat berhasil"],answer:0,explain:"Proyek yang menghasilkan pemahaman jelas ('ini bukan masalah nyata, penyebabnya begini') adalah proyek yang berhasil, meski idenya dihentikan.",hint:"Laporkan temuan & pelajaran jujur, atau poles agar terlihat berhasil?"},
{n:92,type:"tf",micro:"Prototipe & rasa percaya diri",q:"Benar atau Salah: Terbiasa membuat prototipe membuat seseorang lebih percaya diri mencoba ide baru, karena ia tahu bisa menguji dengan cepat & murah sebelum berkomitmen besar.",answer:true,explain:"Keterampilan memprototipe menurunkan 'biaya mencoba', sehingga lebih banyak ide berani yang layak dijajaki.",hint:"Menaikkan keberanian mencoba, atau tidak berpengaruh?"},
{n:93,type:"mcq",micro:"Skenario: prototipe berhasil, sumber daya kurang",q:"Prototipe menunjukkan idemu berhasil, tapi versi sungguhannya butuh dana/izin yang belum ada. Langkah:",options:["Jalankan diam-diam tanpa izin","Pakai hasil prototipe (bukti konkret + temuan) untuk meyakinkan pihak yang bisa memberi dana/izin","Menyerah karena tidak ada dana sekarang"],answer:1,explain:"Prototipe yang berhasil adalah alat persuasi terkuat: 'ini sudah dicoba, ini hasilnya, ini yang dibutuhkan untuk memperbesar'.",hint:"Pakai bukti untuk meyakinkan pemberi dana/izin, atau menyerah / diam-diam?"},
{n:94,type:"mcq",micro:"Skenario: menyeimbangkan poles & fungsi",q:"Untuk pameran proyek, kamu punya waktu terbatas: prototipe berfungsi tapi kasar. Prioritas:",options:["Habiskan semua waktu mengecat & menghias","Sembunyikan bagian yang belum jadi","Pastikan bagian yang menunjukkan cara kerja & temuan tetap jelas; poles hanya bagian yang memengaruhi pemahaman penonton"],answer:2,explain:"Penonton perlu memahami ide & apa yang kamu pelajari, itu yang dipoles. Kerapian murni sekunder.",hint:"Perjelas cara kerja & temuan, atau habiskan waktu menghias?"},
{n:95,type:"tf",micro:"Prototipe untuk ide apa pun",q:"Benar atau Salah: Hampir setiap ide, baik benda, layanan, aturan, kegiatan, maupun tampilan, punya bentuk prototipe murah yang bisa dibuat untuk mengujinya sebelum berkomitmen penuh.",answer:true,explain:"Sketsa, model seadanya, bermain peran, uji skala kecil, prototipe kertas, selalu ada cara cepat & murah menguji inti sebuah ide.",hint:"Hampir semua ide bisa diprototipe murah, atau hanya benda?"},
{n:96,type:"mcq",micro:"Skenario: prototipe mengubah ide jadi lebih kecil",q:"Prototipe menunjukkan ide besarmu terlalu rumit, tapi satu bagian kecilnya sangat berguna. Langkah bijak:",options:["Fokuskan proyek pada bagian kecil yang berguna itu, jalankan & sempurnakan, sisanya bisa menyusul nanti","Tetap kerjakan ide besar yang rumit","Buang semuanya karena ide besar gagal"],answer:0,explain:"Sering versi kecil yang benar-benar berjalan lebih berharga daripada versi besar yang tidak pernah selesai. Prototipe membantu menemukannya.",hint:"Fokus ke bagian kecil yang berguna, atau tetap ide besar / buang semua?"},
{n:97,type:"mcq",micro:"Menilai kualitas proses prototipe",q:"Tanda kamu memprototipe dengan baik:",options:["Kamu tidak pernah menunjukkannya ke siapa pun","Prototipemu cepat & murah, kamu punya pertanyaan jelas tiap kali, kamu menguji dengan pengguna nyata, & idemu berubah berdasar temuan","Prototipemu selalu rapi & tidak pernah berubah"],answer:1,explain:"Proses yang sehat: murah, terarah pertanyaan, diuji nyata, & responsif terhadap temuan.",hint:"Cepat-terarah-diuji-berubah, atau rapi & tidak berubah?"},
{n:98,type:"mcq",micro:"Prototipe & pembelajaran seumur hidup",q:"Kebiasaan 'buat versi kasar dulu, uji, perbaiki' berguna di luar proyek sekolah untuk...",options:["Hanya untuk membuat produk","Tidak ada gunanya di kehidupan biasa","Hampir semua hal: menulis (draf kasar), memasak (coba porsi kecil), merencanakan acara (uji satu bagian), belajar keterampilan baru"],answer:2,explain:"'Prototipe' adalah cara berpikir: mulai kecil & kasar, belajar dari kenyataan, perbaiki. Ini berlaku luas.",hint:"Berguna untuk banyak hal, atau hanya produk?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'dari ide ke prototipe':",options:["Ubah ide di kepala jadi sesuatu yang bisa dilihat & dicoba secepat & semurah mungkin, lalu belajar dari reaksi nyata & perbaiki bertahap","Rancang sesempurna mungkin di kertas sebelum membuat apa pun","Buat versi final sekali jadi"],answer:0,explain:"Konkret-cepat-murah → uji nyata → perbaiki berulang. Bukti mengalahkan tebakan; putaran mengalahkan kesempurnaan sekali jadi.",hint:"Konkret cepat lalu belajar & perbaiki, atau sempurna di kertas dulu?"},
{n:100,type:"open",micro:"Kapstone: rencana dari ide ke versi siap pakai",q:"Pilih satu masalah nyata & satu ide untuk mengatasinya. Buat rencana lengkap dari ide ke versi siap pakai: (a) pertanyaan/asumsi paling berisiko, (b) prototipe pertama (bentuk, bahan, waktu) & apa yang diuji, (c) rencana pengujian (siapa, tugas, yang diamati), (d) bagaimana kamu akan memutuskan lanjut/ubah/hentikan, (e) gambaran prototipe kedua bila lanjut, (f) tanda bahwa kamu siap berhenti memprototipe & membuat versi sungguhan.",sample:"Masalah: siswa sering melewatkan pengumuman penting karena hanya disampaikan lisan di pagi hari & yang telat/absen tidak tahu. Ide: 'papan pengumuman digital sederhana', satu layar/whiteboard di lokasi strategis yang diperbarui tiap pagi + salinan foto dikirim ke grup kelas. (a) Asumsi paling berisiko: siswa akan benar-benar melihat papan/foto itu & tidak tetap mengandalkan 'nanti ada yang memberi tahu'. (b) Prototipe pertama: papan tulis kecil di dekat pintu gerbang berisi 3 pengumuman terpenting hari itu, ditulis petugas piket jam 06.45, + satu foto dikirim ke grup kelas. Bahan: papan tulis kecil bekas, spidol. Waktu menyiapkan sistem: 30 menit + 5 menit tiap pagi. Yang diuji: apakah orang melihat & mengingatnya. (c) Pengujian: selama 5 hari, tiap siang aku tanya 8 siswa acak (termasuk yang sering telat) 'apa 3 pengumuman hari ini?' & catat berapa yang tahu, dari mana mereka tahu (papan/foto/teman/tidak tahu). (d) Keputusan: jika lebih dari separuh tahu & menyebut papan/foto sebagai sumber, LANJUT. Jika kebanyakan masih 'dari teman' atau 'tidak tahu', UBAH, coba lokasi papan yang lebih dilewati atau tambahkan pengingat di grup pada jam istirahat. Jika hampir tidak ada yang peduli meski sudah dicoba dua cara, HENTIKAN & selidiki apakah masalah sebenarnya berbeda. (e) Prototipe kedua (bila lanjut): pindahkan papan ke depan kantin (lebih ramai), pakai warna untuk menandai pengumuman 'wajib' vs 'info', kirim foto dua kali (pagi & sebelum pulang). (f) Siap membuat versi sungguhan ketika: dua putaran menunjukkan mayoritas siswa konsisten tahu pengumuman dari sistem ini, tidak ada masalah besar baru, & yang tersisa hanya soal memperbagus (papan permanen, jadwal petugas resmi).",explain:"Jawaban baik: asumsi berisiko yang menyangkut perilaku, prototipe pertama yang sangat murah & cepat dengan hal spesifik yang diuji, rencana pengujian yang mengukur sesuatu (berapa siswa tahu, dari sumber mana), tiga cabang keputusan yang jelas & masuk akal, prototipe kedua yang memperbaiki berdasar kemungkinan temuan, & kriteria berhenti yang konkret (bukan 'kalau sudah bagus').",hint:"Bagian (d) & (f) yang paling sering lemah, buat kriterianya bisa diperiksa dengan angka atau pengamatan, bukan perasaan."},
];
